import {SENSOR, DISPLAY_RATE, createInitialState, loadState, saveState, makeDemoPoints, acceptFeedback, undoLearning, resetLearning, exportRecordingCSV, exportReportPDF, statistics, slicePoints, formatDuration, generateId} from './data.js';
import {createSensorViewer} from './sensor3d.js';

const $ = (s,root=document)=>root.querySelector(s);
const esc = v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = v=>structuredClone(v);
const num = v=>Number(v).toLocaleString('de-DE',{minimumFractionDigits:3,maximumFractionDigits:3});
const rate = v=>v>=1000?`${(v/1000).toLocaleString('de-DE')} kHz`:`${v} Hz`;
const time = v=>new Date(v).toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'});
const date = v=>new Date(v).toLocaleDateString('de-DE',{day:'2-digit',month:'short',year:'numeric'});
const icons={
 wave:'M2 12h4l3-8 5 16 3-8h5', monitor:'M3 4h18v12H3z M8 21h8 M12 16v5', folder:'M3 7h7l2-3h9v16H3z', sliders:'M5 3v5m0 4v9 M2 8h6 M12 3v10m0 4v4 M9 13h6 M19 3v3m0 4v11 M16 6h6', sun:'M12 3v2m0 14v2M3 12h2m14 0h2 M5.6 5.6L7 7m10 10 1.4 1.4 M5.6 18.4 1.4-1.4M17 7l1.4-1.4 M16 12a4 4 0 1 1-8 0 4 4 0 0 1 8 0', moon:'M20 15.5A8.5 8.5 0 0 1 8.5 4 8.5 8.5 0 1 0 20 15.5',
 chevron:'m9 5 7 7-7 7', down:'m6 9 6 6 6-6', back:'m12 5-7 7 7 7 M5 12h16', arrow:'M4 12h16m-6-6 6 6-6 6', close:'m6 6 12 12M6 18 18 6', check:'m5 12 4 4L19 6', info:'M12 8v.01M12 11v6 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0', alert:'m12 3 10 18H2z M12 9v5m0 3v.01', pause:'M8 5v14 M16 5v14', play:'m7 4 13 8-13 8z', zero:'M4 12h16 M12 4v16 M17 7a7 7 0 1 1-10 10', pin:'m9 3 6 0-1 6 4 4H6l4-4z M12 13v8', box:'m12 2 9 5v10l-9 5-9-5V7z M3 7l9 5 9-5 M12 12v10',
 edit:'m15 4 5 5-11 11H4v-5z M13 6l5 5', search:'M20 20l-5-5 M17 10a7 7 0 1 1-14 0 7 7 0 0 1 14 0', download:'M12 3v12m-5-5 5 5 5-5 M4 16v5h16v-5', file:'M5 3h9l5 5v13H5z M14 3v6h5 M8 13h8m-8 4h6', compare:'M4 7h15m-4-4 4 4-4 4 M20 17H5m4-4-4 4 4 4', reset:'M3 10a9 9 0 1 1 2 8 M3 4v6h6', help:'M9 8a3 3 0 1 1 5 2c-2 1-2 2-2 3 M12 17v.01 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0', plug:'M8 3v5m8-5v5M6 8h12v3a6 6 0 0 1-12 0z M12 17v5', plus:'M12 5v14M5 12h14', save:'M4 3h13l4 4v14H3V3z M7 3v6h9V3 M7 14h10v7', clock:'M12 7v5l3 2 M22 12a10 10 0 1 1-20 0 10 10 0 0 1 20 0', network:'M8 3h8v6H8z M3 16h6v5H3z M15 16h6v5h-6z M12 9v4 M6 16v-3h12v3', link:'m9 15 6-6 M8 16l-2 2a4 4 0 0 1-6-6l4-4a4 4 0 0 1 6 0 M16 8l2-2a4 4 0 0 1 6 6l-4 4a4 4 0 0 1-6 0', spark:'m12 3 2.7 6.3L21 12l-6.3 2.7L12 21l-2.7-6.3L3 12l6.3-2.7z', trash:'M3 6h18 M9 6V3h6v3 M6 6l1 15h10l1-15 M10 10v7m4-7v7'
};
const icon=(name,cls='')=>`<svg class="icon ${cls}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${icons[name]||icons.info}"/></svg>`;
let state,bootError='';try{state=loadState()}catch(e){state=createInitialState();bootError=e.message}
const rt={route:'monitor',mode:'demo',connected:true,paused:false,elapsed:60,value:37.5,points:makeDemoPoints(),markers:[],zeroOffset:0,window:30,record:null,saving:false,unsaved:null,lastSaved:null,deviation:null,lastFeedback:null,cooldown:0,scenario:'normal',feedback:[],viewer:null,dialogViewer:null,led:{state:'green',output:'green'},selected:new Set(),analysis:null,offset:0,replayTime:0,replayPlaying:false,replaySpeed:1,reportStart:0,reportEnd:60,setupStep:1,setupMode:'demo',setupChecked:false,socket:null,socketTimer:null,bridgeUrl:state.settings.bridgeUrl||'ws://localhost:8765',connectionError:'',storageError:bootError,charts:[],tick:0};
let toastTimer,dialogType='',dialogContext=null,lastTick=performance.now();
const profile=()=>state.profiles.find(p=>p.id===state.activeProfileId)||state.profiles[0];
const recording=()=>state.recordings.find(r=>r.id===[...rt.selected][0]);
const vnum=(v,offset=rt.zeroOffset)=>num(v-offset);
const currentStatus=()=>!rt.connected?'Nicht verbunden':rt.saving?'Wird gespeichert':rt.unsaved?'Noch nicht gespeichert':rt.record?'Aufnahme läuft':rt.paused?'Anzeige pausiert':'Liveanzeige';
function persist(){try{saveState(state);rt.storageError='';return true}catch(e){rt.storageError=e.message;toast(e.message);return false}}
function toast(message){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.classList.add('show');toastTimer=setTimeout(()=>el.classList.remove('show'),4500)}
function setProfile(p){state.profiles=state.profiles.map(x=>x.id===p.id?p:x)}
function ledColor(value){return{green:'var(--good)',yellow:'var(--warn)',red:'var(--bad)',off:'var(--faint)',unknown:'var(--muted)'}[value]||'var(--muted)'}
function ledMeaning(name,value){return({state:{green:'Das Objekt liegt im Messbereich des Sensors.',yellow:'Das Objekt befindet sich in der Messbereichsmitte.',red:'Der Sensor meldet einen Messfehler. Zieloberfläche und Messbereich prüfen.',off:'Der Laser ist ausgeschaltet.',unknown:'Der Sensorstatus ist nicht verfügbar.'},output:{green:'Die digitale Messwertausgabe über RS422 ist aktiv.',yellow:'Die Messwertausgänge sind deaktiviert.',red:'Die analoge Ausgabe über 4–20 mA ist aktiv. Diese Farbe kennzeichnet den Ausgabemodus.',off:'Der Sensor ist ausgeschaltet oder ohne Versorgung.',unknown:'Der Ausgabestatus ist nicht verfügbar.'}})[name][value]}
function route(name){location.hash=name}
function header(){return `<header class="app-header"><a href="#monitor" class="brand" aria-label="Micro-Epsilon Monitor"><span class="brand-mark">${icon('wave')}</span><span><span class="brand-name">MICRO-EPSILON</span><div class="brand-sub">Sensor Monitor · optoNCDT 1420</div></span></a><nav class="nav" aria-label="Hauptnavigation"><a href="#monitor" ${rt.route==='monitor'?'aria-current="page"':''}>Monitor</a><a href="#recordings" ${rt.route==='recordings'?'aria-current="page"':''}>Aufzeichnungen</a><a href="#advanced" ${rt.route==='advanced'?'aria-current="page"':''}>Advanced</a></nav><div class="header-right"><button class="mode-button" data-action="connection"><span class="dot ${rt.mode==='demo'?'accent':rt.connected?'good':'bad'}"></span>${rt.mode==='demo'?'Demo-Modus':rt.connected?'Sensor verbunden':'Verbindung fehlt'}${icon('down')}</button><button class="icon-button" data-action="theme" aria-label="Farbschema wechseln" title="Farbschema wechseln">${icon(document.documentElement.dataset.theme==='light'?'moon':'sun')}</button><button class="icon-button" data-action="help" aria-label="Hilfe öffnen">${icon('help')}</button></div></header>`}
function footer(){return `<footer class="app-footer"><span>MICRO-EPSILON / optoNCDT 1420-25</span><span>${rt.mode==='demo'?'Demo · simulierte Daten · 5 Werte/s':'Messbrücke · echte Sensordaten'} <span aria-hidden="true">/</span> lokal in diesem Browser</span><button class="footer-link" data-action="help">Hinweise & Hilfe ${icon('chevron')}</button></footer>`}
function globalNotices(){return `${rt.storageError?`<div class="notice error">${icon('alert')}<div><strong>Lokales Speichern ist nicht verfügbar</strong><p>${esc(rt.storageError)}</p></div></div>`:''}${rt.connectionError?`<div class="notice error">${icon('plug')}<div class="notice-body"><strong>Sensor nicht erreichbar</strong><p>${esc(rt.connectionError)} Bereits erfasste Daten bleiben erhalten.</p><div class="notice-actions"><button class="btn compact" data-action="reconnect">${icon('reset')} Erneut verbinden</button><button class="btn quiet compact" data-action="connection">Verbindung prüfen</button><button class="btn quiet compact" data-action="demo">Demo verwenden</button></div></div></div>`:''}`}
function learningNotice(){if(rt.deviation){const d=rt.deviation,p=d.profile;return `<section class="notice" aria-label="Messabweichung">${icon('alert')}<div class="notice-body"><strong>Dieser Messwert liegt außerhalb der Auswertungsgrenzen.</strong><p><span class="mono">${num(d.value)} mm</span> · erwartet: <span class="mono">${num(p.learnedLower)}–${num(p.learnedUpper)} mm</span>. Ist die Abweichung für deinen Versuch in Ordnung?</p><input class="feedback-note" id="feedback-note" placeholder="Optionale Begründung …" aria-label="Begründung zur Bewertung" maxlength="300"><div class="notice-actions"><button class="btn compact" data-action="feedback" data-accepted="true">${icon('check')} Messwert ist akzeptabel</button><button class="btn quiet compact" data-action="feedback" data-accepted="false">${icon('close')} Nicht akzeptabel</button></div></div><button class="icon-button" data-action="dismiss-deviation" aria-label="Später bewerten">${icon('close')}</button></section>`}
 if(rt.lastFeedback){const e=rt.lastFeedback;return `<section class="notice success">${icon('check')}<div class="notice-body"><strong>${e.changed?'Auswertung für künftige Messwerte angepasst':'Bewertung gespeichert'}</strong><p>${e.changed?`Gelernte Grenzen: ${num(e.previousLower)}–${num(e.previousUpper)} → ${num(e.nextLower)}–${num(e.nextUpper)} mm. Die Sollgrenzen bleiben erhalten.`:esc(e.reason)}</p>${e.changed?'<button class="text-button small" data-action="undo-learning">Anpassung rückgängig machen</button>':''}</div><button class="icon-button" data-action="dismiss-feedback" aria-label="Hinweis schließen">${icon('close')}</button></section>`}return ''}
function monitor(){const p=profile();return `<div class="page-heading"><div><h1>Monitor</h1><p>Deine Messung. Alles Wesentliche im Blick.</p></div><span class="status-label"><span class="dot ${rt.connected?'good':'bad'}"></span>${rt.mode==='demo'?'Demo-Sensor bereit':rt.connected?'Sensor verbunden':'Nicht verbunden'}</span></div>${!state.setupComplete?`<div class="onboarding"><div><div class="row">${icon('plug')}<strong>Zum ersten Mal hier?</strong></div><p>In vier Schritten zur ersten Messung.</p></div><div class="row"><a class="btn compact" href="#setup">Einrichtung starten ${icon('arrow')}</a><button class="icon-button" data-action="dismiss-setup" aria-label="Einrichtungshinweis ausblenden">${icon('close')}</button></div></div>`:''}<div class="profile-bar"><div class="profile-selector">${icon('sliders','profile-icon')}<div><label class="sr-only" for="profile-select">Messprofil wählen</label><select id="profile-select" data-field="profile" ${rt.record?'disabled':''}>${state.profiles.map(x=>`<option value="${esc(x.id)}" ${x.id===p.id?'selected':''}>${esc(x.name)}</option>`).join('')}</select><div class="profile-sub">${esc(SENSOR.model)} <span aria-hidden="true">·</span> Profil ${rate(p.rate)} <span aria-hidden="true">·</span> mm</div></div></div><button class="btn compact quiet" data-action="edit-profile" ${rt.record?'disabled':''}>${icon('edit')} Profil bearbeiten</button></div><div id="learning-notice">${learningNotice()}</div><div class="monitor-grid"><section class="panel measurement-panel" aria-label="Aktuelle Messung"><div class="reading-zone"><div class="reading-top"><span class="eyebrow">${rt.zeroOffset?'Relativer Abstand':'Abstand zum Objekt'}</span><span class="status-label" id="record-state"><span class="dot ${rt.record?'bad':rt.connected?'good':'bad'}"></span>${currentStatus()}</span></div><div class="reading-main"><span id="reading-value" class="reading-value">${rt.connected?vnum(rt.value):'—'}</span><span class="reading-unit">mm</span></div><div class="reading-sub" id="reading-sub">${rt.zeroOffset?`Nullpunkt: ${num(rt.zeroOffset)} mm · `:''}Sollwert <span id="target-value">${vnum(p.target)} mm</span> <span aria-hidden="true">·</span> Abweichung <span id="deviation-value">${num(rt.value-p.target)} mm</span></div><div class="tolerance"><div class="tolerance-track"><div class="tolerance-corridor"></div><div class="tolerance-mid"></div><div class="tolerance-pointer" id="tolerance-pointer"></div></div><div class="tolerance-labels"><span>${vnum(p.lower)} mm</span><span>Sollbereich</span><span>${vnum(p.upper)} mm</span></div></div><div id="reading-state" class="reading-state good"><span class="dot"></span>Innerhalb des Sollbereichs</div><div class="measurement-actions"><button class="btn primary record" data-action="record" ${!rt.connected||rt.saving?'disabled':''}>${rt.record?'<span class="stop-square"></span> Stoppen & speichern':rt.saving?'Wird gespeichert …':'<span class="record-dot"></span> Aufnahme starten'}</button><button class="btn quiet" data-action="pause" ${!rt.connected||rt.record?'disabled':''}>${icon(rt.paused?'play':'pause')} ${rt.paused?'Fortsetzen':'Anzeige pausieren'}</button><button class="btn quiet" data-action="zero" ${!rt.connected||rt.record?'disabled':''}>${icon('zero')} ${rt.zeroOffset?'Nullpunkt lösen':'Nullpunkt setzen'}</button></div>${rt.record?`<div class="recording-meta"><span class="recording row"><span class="dot"></span><span id="record-duration">00:00</span></span><span>${esc(rt.record.name)}.csv</span><span>Browser · lokal</span></div>`:rt.unsaved?`<div class="recording-meta"><span class="warn">Noch nicht gespeichert</span><button class="text-button" data-action="retry-save">Erneut speichern</button><button class="text-button" data-action="export-unsaved">CSV sichern</button></div>`:rt.lastSaved?`<div class="recording-meta"><span class="good">${icon('check')} Gespeichert</span><span>${esc(rt.lastSaved.name)}</span><a href="#recordings" class="accent">Öffnen ${icon('arrow')}</a></div>`:''}</div><div class="chart-section"><div class="chart-head"><div><h2>Messverlauf</h2><div class="chart-legend"><span><i class="legend-line"></i>Abstand</span><span><i class="legend-line spec"></i>Sollgrenzen</span></div></div><div class="segmented" aria-label="Angezeigter Zeitraum">${[10,30,60].map(n=>`<button data-action="window" data-value="${n}" class="${rt.window===n?'active':''}" aria-pressed="${rt.window===n}">${n} s</button>`).join('')}</div></div><div class="chart-wrap"><canvas id="live-chart" aria-label="Live-Diagramm: Abstand in Millimetern über Zeit" role="img"></canvas><div class="chart-tooltip hidden" id="live-tooltip"></div></div><form class="note-entry" data-form="marker">${icon('pin')}<label class="sr-only" for="marker-note">Notiz zur aktuellen Messung</label><input id="marker-note" name="note" placeholder="Was ist gerade passiert? Notiz hinzufügen …" maxlength="300" required ${!rt.connected?'disabled':''}><button class="btn compact quiet" type="submit" ${!rt.connected?'disabled':''}>Markieren ${icon('plus')}</button></form><div class="marker-list">${rt.markers.slice(-4).map(m=>`<button class="marker-chip" data-action="edit-marker" data-id="${esc(m.id)}">${icon('pin')} ${formatDuration(m.t)} · ${esc(m.note)}</button>`).join('')}</div></div><div class="monitor-foot"><span id="sample-count">${rt.points.length} Darstellungswerte</span><span>${rt.mode==='demo'?'Demo · 5 Werte/s':'Sensor · Messbrücke'} / Zeit in s · Abstand in mm</span></div></section><aside class="side-stack" aria-label="Sensor und Auswertung"><section class="panel sensor-card"><div class="panel-heading"><div><span class="eyebrow">Dein Sensor</span><h3>optoNCDT 1420-25</h3></div><span class="dot good" id="device-connected-dot"></span></div><div class="sensor-mini" id="mini-viewer"></div><div class="device-leds"><button class="led-status" data-action="sensor" data-led="state"><span class="dot" id="state-dot" style="color:${ledColor(rt.led.state)}"></span>State</button><button class="led-status" data-action="sensor" data-led="output"><span class="dot" id="output-dot" style="color:${ledColor(rt.led.output)}"></span>Output</button></div><div class="device-bottom"><span class="muted small">Schematische 3D-Ansicht</span><button class="text-button small" data-action="sensor">Sensorstatus ${icon('arrow')}</button></div><div class="metric-row"><span class="muted">Messbereich</span><span class="mono">25–50 mm</span></div></section><section class="panel learning-card"><div class="panel-heading"><h2>Adaptive Auswertung</h2><span class="learning-state ${p.learning?'good':'muted'}"><span class="dot"></span>${p.learning?'Aktiv':'Pausiert'}</span></div><p class="learning-description">Du bewertest Abweichungen. Die Auswertung lernt für die nächsten Messwerte dazu.</p><div class="bound-row"><span class="muted">Sollgrenzen</span><span class="mono">${num(p.lower)}–${num(p.upper)}</span></div><div class="bound-row"><span class="muted">Gelernte Grenzen</span><span class="mono">${num(p.learnedLower)}–${num(p.learnedUpper)}</span></div><div class="row between" style="margin-top:15px"><button class="text-button muted small" data-action="toggle-learning">${icon(p.learning?'pause':'play')} ${p.learning?'Lernen pausieren':'Lernen fortsetzen'}</button><a href="#advanced" class="text-button muted small">Verlauf ${icon('chevron')}</a></div>${rt.mode==='demo'?`<hr class="divider"><span class="eyebrow">Demo ausprobieren</span><div class="demo-controls"><button class="btn" data-action="simulate-deviation" ${!rt.connected?'disabled':''}>Abweichung erzeugen ${icon('arrow')}</button><button class="btn" data-action="simulate-disconnect">${rt.connected?'Verbindung unterbrechen':'Erneut verbinden'} ${icon(rt.connected?'plug':'reset')}</button><p>Simulation · regelbasierte Lernanpassung</p></div>`:''}</section></aside></div>`}
function recordingsView(){const selected=[...rt.selected].map(id=>state.recordings.find(x=>x.id===id)).filter(Boolean);return `<div class="page-heading"><div><h1>Aufzeichnungen</h1><p>Gespeicherte Messungen wiedergeben, vergleichen und dokumentieren.</p></div><span class="status-label">${state.recordings.length} Messungen</span></div><div class="recordings-toolbar"><span class="muted small">Deine Daten bleiben in diesem Browser.</span><div class="search-box">${icon('search')}<input id="run-search" type="search" value="${esc(rt.search||'')}" placeholder="Messung suchen …" aria-label="Aufzeichnungen durchsuchen"></div></div><section class="panel"><div class="table-wrap"><table class="runs-table"><thead><tr><th><span class="sr-only">Auswahl</span></th><th>Messung</th><th>Datum</th><th>Dauer</th><th>Ereignisse</th><th>Quelle</th><th><span class="sr-only">Aktionen</span></th></tr></thead><tbody>${state.recordings.map(r=>`<tr data-run-id="${esc(r.id)}" class="${rt.selected.has(r.id)?'selected':''}"><td><input type="checkbox" data-field="run" value="${esc(r.id)}" ${rt.selected.has(r.id)?'checked':''} aria-label="${esc(r.name)} auswählen"></td><td><span class="run-name">${esc(r.name)}</span><span class="run-profile">${esc(r.profile.name)} · ${rate(r.profile.rate)}</span></td><td>${date(r.createdAt)}<div class="run-profile mono">${time(r.createdAt)}</div></td><td class="mono">${formatDuration(r.duration)}</td><td class="mono">${r.markers?.length||0}</td><td><span class="badge"><span class="dot ${r.source==='demo'?'muted':'good'}"></span>${r.source==='demo'?'Demo':'Sensor'}</span>${r.interrupted?'<div class="small warn">Unterbrochen</div>':''}</td><td><button class="icon-button" data-action="run-menu" data-id="${esc(r.id)}" aria-label="${esc(r.name)} bearbeiten">${icon('edit')}</button></td></tr>`).join('')}</tbody></table></div>${!state.recordings.length?`<div class="empty">${icon('folder')}<h2>Noch keine Aufzeichnung</h2><p>Starte im Monitor eine Aufnahme. Nach dem Speichern findest du sie hier.</p><a class="btn primary" href="#monitor">Zum Monitor ${icon('arrow')}</a></div>`:''}<div class="selection-bar"><span class="small muted">${selected.length?`${selected.length} ${selected.length===1?'Messung':'Messungen'} ausgewählt`:'Wähle eine Messung aus.'}</span><div class="row"><button class="btn ${rt.analysis==='replay'?'primary':''}" data-action="analysis" data-view="replay" ${selected.length!==1?'disabled':''}>${icon('play')} Wiedergeben</button><button class="btn ${rt.analysis==='compare'?'primary':''}" data-action="analysis" data-view="compare" ${selected.length!==2?'disabled':''}>${icon('compare')} Vergleichen</button><button class="btn ${rt.analysis==='report'?'primary':''}" data-action="analysis" data-view="report" ${selected.length!==1?'disabled':''}>${icon('file')} PDF-Bericht</button><button class="btn quiet" data-action="csv" ${selected.length!==1?'disabled':''} aria-label="Ausgewählte Messung als CSV herunterladen">${icon('download')} CSV</button></div></div></section>${analysisView(selected)}`}
function analysisView(runs){if(!rt.analysis)return '';const r=runs[0];if(!r)return '';if(rt.analysis==='compare'&&runs.length!==2)return '';if(rt.analysis!=='compare'&&runs.length!==1)return '';const stats=statistics(r.points);if(rt.analysis==='report')return reportView(r);return `<section class="panel analysis-panel"><div class="panel-heading"><div><h2>${rt.analysis==='compare'?'Messungen vergleichen':'Messung wiedergeben'}</h2><p>${esc(r.name)}${runs[1]?` / ${esc(runs[1].name)}`:''}</p></div><button class="icon-button" data-action="close-analysis" aria-label="Analyse schließen">${icon('close')}</button></div>${rt.analysis==='compare'&&r.profile.unit!==runs[1].profile.unit?'<div class="notice error">Die Einheiten sind nicht kompatibel.</div>':`<div class="chart-legend"><span><i class="legend-line"></i>${esc(r.name)}</span>${runs[1]?`<span><i class="legend-line ref"></i>${esc(runs[1].name)}</span>`:''}</div><div class="chart-wrap"><canvas id="analysis-chart" role="img" aria-label="${rt.analysis==='compare'?'Überlagerte Messkurven':'Gespeicherter Messverlauf'}"></canvas></div>${rt.analysis==='compare'?`<div class="analysis-controls"><div class="field"><label for="compare-offset">Zeitversatz der Referenz: <span class="mono" id="offset-label">${rt.offset.toFixed(1)} s</span></label><input id="compare-offset" data-field="offset" type="range" min="-10" max="10" value="${rt.offset}" step="0.2"></div><button class="btn compact" data-action="align">${icon('compare')} Am Anfang ausrichten</button></div><div class="stats-grid"><div><span class="eyebrow">Mittlere Differenz</span><div class="stat-value" id="compare-mean">—</div><div class="stat-label">A − Referenz, gemeinsamer Zeitraum</div></div><div><span class="eyebrow">Größte Differenz</span><div class="stat-value" id="compare-max">—</div><div class="stat-label">Betrag der Abweichung</div></div><div><span class="eyebrow">Gemeinsame Werte</span><div class="stat-value" id="compare-count">—</div><div class="stat-label">Zeitlich zugeordnete Messpunkte</div></div></div>`:`<div class="replay-controls"><button class="btn compact" data-action="replay-toggle" aria-label="${rt.replayPlaying?'Wiedergabe pausieren':'Wiedergabe starten'}">${icon(rt.replayPlaying?'pause':'play')}</button><span class="mono small" id="replay-time">${formatDuration(rt.replayTime)}</span><input type="range" data-field="replay" aria-label="Wiedergabeposition" min="0" max="${r.duration}" step=".2" value="${rt.replayTime}"><span class="mono small">${formatDuration(r.duration)}</span><select data-field="speed" aria-label="Wiedergabegeschwindigkeit">${[.5,1,2,4].map(s=>`<option value="${s}" ${rt.replaySpeed===s?'selected':''}>${s}×</option>`).join('')}</select></div><div class="row between" style="margin-top:15px"><span class="small muted" id="replay-value">${num(r.points[0]?.value)} mm</span><div class="segmented" aria-label="Wiedergabe-Zoom">${[10,30,0].map(n=>`<button data-action="replay-window" data-value="${n}" class="${(rt.replayWindow||0)===n?'active':''}">${n?n+' s':'Gesamt'}</button>`).join('')}</div></div><div class="stats-grid"><div><span class="eyebrow">Minimum</span><div class="stat-value">${num(stats.min)} <small>mm</small></div></div><div><span class="eyebrow">Mittelwert</span><div class="stat-value">${num(stats.mean)} <small>mm</small></div></div><div><span class="eyebrow">Maximum</span><div class="stat-value">${num(stats.max)} <small>mm</small></div></div></div>${r.markers?.length?`<div class="marker-list">${r.markers.map(m=>`<button class="marker-chip" data-action="jump-marker" data-value="${m.t}">${icon('pin')} ${formatDuration(m.t)} · ${esc(m.note)}</button>`).join('')}</div>`:''}`}`}</section>`}
function reportView(r){let start=rt.reportStart,end=rt.reportEnd;const points=r.points.filter(p=>p.t>=start&&p.t<=end);const s=statistics(points);return `<section class="panel analysis-panel"><div class="panel-heading"><div><h2>Messbericht erstellen</h2><p>Wähle den Zeitraum und prüfe die Vorschau.</p></div><button class="icon-button" data-action="close-analysis" aria-label="Bericht schließen">${icon('close')}</button></div><div class="report-grid"><div class="report-options stack"><div class="fields"><div class="field"><label for="report-start">Beginn in Sekunden</label><input id="report-start" data-field="report-start" type="number" min="0" max="${r.duration}" step=".2" value="${start}"></div><div class="field"><label for="report-end">Ende in Sekunden</label><input id="report-end" data-field="report-end" type="number" min="0" max="${r.duration}" step=".2" value="${end}"></div></div><p class="small muted">Enthält Diagramm, Sensorinformationen, Einstellungen, Notizen und Bewertungen.</p><button class="btn primary" data-action="pdf">${icon('download')} PDF herunterladen</button><p class="small muted">${r.source==='demo'?'Der Bericht kennzeichnet die Messwerte als simulierte Demodaten.':'Der Bericht enthält die Daten der angeschlossenen Messbrücke.'}</p></div><article class="report-paper"><div class="report-brand">MICRO-EPSILON / MESSDOKUMENTATION</div><h2>Messbericht</h2><p>${esc(r.name)} · ${date(r.createdAt)}</p><div class="chart-wrap"><canvas id="report-chart" role="img" aria-label="Diagrammvorschau des ausgewählten Berichtszeitraums"></canvas></div><dl><div><dt>Sensor</dt><dd>${esc(r.sensor)}</dd></div><div><dt>Zeitraum</dt><dd>${formatDuration(start)}–${formatDuration(end)}</dd></div><div><dt>Profil</dt><dd>${esc(r.profile.name)}</dd></div><div><dt>Profil-Messrate</dt><dd>${rate(r.profile.rate)}</dd></div><div><dt>Sollwert</dt><dd>${num(r.profile.target)} mm</dd></div><div><dt>Minimum / Maximum</dt><dd>${s.count?num(s.min)+' / '+num(s.max):'—'} mm</dd></div></dl><h3>Ereignisse & Notizen</h3>${r.markers.filter(m=>m.t>=start&&m.t<=end).map(m=>`<div class="report-note"><span class="mono">${formatDuration(m.t)}</span> · ${esc(m.note)}</div>`).join('')||'<p>Keine Notizen in diesem Zeitraum.</p>'}<h3>Auswertung</h3><p>${r.feedback?.filter(f=>f.t>=start&&f.t<=end).length||0} Bewertungen · Parameterstand Version ${r.profile.version}</p><div class="report-disclaimer">${r.source==='demo'?'DEMO · SIMULIERTE MESSDATEN':'SENSORDATEN · MESSBRÜCKE'}<br>${points.length} erfasste Werte · Originaldaten bleiben erhalten.</div></article></div></section>`}

function advancedView(){const p=profile();const history=[...(p.history||[])].reverse();return `<div class="page-heading"><div><h1>Advanced</h1><p>Verbindung, Messprofil und Auswertung im Detail.</p></div><a href="#monitor" class="text-button muted">${icon('back')} Zum Monitor</a></div><form data-form="settings"><div class="advanced-grid"><section class="panel advanced-panel"><div class="panel-heading"><h2><span class="section-number">01</span>Sensor & Verbindung</h2>${icon('plug','muted')}</div><div class="metric-row"><span class="muted">Sensormodell</span><span class="mono">${esc(SENSOR.model)}</span></div><div class="metric-row"><span class="muted">Physischer Messbereich</span><span class="mono">25–50 mm</span></div><div class="metric-row"><span class="muted">Sensorausgang / Adapter</span><span class="small">${esc(SENSOR.interface)}</span></div><div class="metric-row"><span class="muted">Datenquelle</span><span class="small">${rt.mode==='demo'?'Simulierter Demo-Sensor':'WebSocket-Messbrücke'}</span></div><div class="field"><label for="bridge-url">Adresse der lokalen Messbrücke</label><input id="bridge-url" name="bridgeUrl" type="url" value="${esc(rt.bridgeUrl)}" placeholder="ws://localhost:8765"><small>Für echte Sensorwerte benötigt der Browser eine lokale Verbindung zum Sensor.</small></div><div class="row wrap" style="margin-top:15px"><button type="button" class="btn compact" data-action="connect-bridge">${icon('link')} Messbrücke verbinden</button><button type="button" class="btn quiet compact" data-action="bridge-help">Schnittstellenformat ${icon('info')}</button></div></section><section class="panel advanced-panel"><div class="panel-heading"><h2><span class="section-number">02</span>Messprofil & Darstellung</h2>${icon('sliders','muted')}</div><p>Aktives Profil: <strong>${esc(p.name)}</strong>. Änderungen gelten für künftige Messungen.</p><div class="fields"><div class="field"><label for="setting-rate">Profil-Messrate</label><select id="setting-rate" name="rate">${SENSOR.rates.map(n=>`<option value="${n}" ${p.rate===n?'selected':''}>${rate(n)}</option>`).join('')}</select></div><div class="field"><label for="setting-window">Diagramm-Zeitraum</label><select id="setting-window" name="window">${[10,30,60].map(n=>`<option value="${n}" ${p.window===n?'selected':''}>${n} Sekunden</option>`).join('')}</select></div></div><div class="metric-row"><span class="muted">Einheit</span><span class="mono">Millimeter (mm)</span></div><div class="info-line">${icon('info')}<span>Die Demo zeigt 5 Werte pro Sekunde. Eine Profil-Messrate beschreibt die gewünschte Sensorkonfiguration; Hardwareparameter werden über die Messbrücke eingerichtet.</span></div><div class="row wrap" style="margin-top:17px"><button type="button" class="btn compact" data-action="edit-profile">${icon('edit')} Sollgrenzen bearbeiten</button><button type="button" class="btn quiet compact" data-action="zero" ${rt.record?'disabled':''}>${icon('zero')} ${rt.zeroOffset?'Nullpunkt lösen':'Nullpunkt setzen'}</button></div></section><section class="panel advanced-panel"><div class="panel-heading"><h2><span class="section-number">03</span>Adaptives Lernen</h2><span class="learning-state ${p.learning?'good':'muted'}"><span class="dot"></span>${p.learning?'Aktiv':'Pausiert'}</span></div><p>Akzeptierte Abweichungen erweitern die gelernten Auswertungsgrenzen um einen kleinen Puffer. Nicht akzeptierte Werte bleiben als Abweichung dokumentiert.</p><div class="metric-row"><span class="muted">Festgelegte Sollgrenzen</span><span class="mono">${num(p.lower)}–${num(p.upper)} mm</span></div><div class="metric-row"><span class="muted">Gelernte Auswertungsgrenzen</span><span class="mono">${num(p.learnedLower)}–${num(p.learnedUpper)} mm</span></div><div class="metric-row"><span class="muted">Parameterstand</span><span class="mono">Version ${p.version}</span></div><div class="row wrap" style="margin-top:18px"><button type="button" class="btn compact" data-action="toggle-learning">${icon(p.learning?'pause':'play')} ${p.learning?'Pausieren':'Fortsetzen'}</button><button type="button" class="btn quiet compact" data-action="undo-learning" ${!history.some(h=>h.changed)?'disabled':''}>${icon('back')} Rückgängig</button><button type="button" class="btn quiet compact" data-action="reset-learning">${icon('reset')} Zurücksetzen</button></div><div class="info-line">${icon('info')}<span>Regelbasierte Lernanpassung in der Anwendung. Originaldaten und Sollgrenzen werden nicht überschrieben.</span></div></section><section class="panel advanced-panel"><div class="panel-heading"><h2><span class="section-number">04</span>Bewertungen & Änderungen</h2><span class="muted mono small">${history.length}</span></div><div class="history-list">${history.length?history.map(h=>`<div class="history-item"><div class="row between"><strong>${h.type==='feedback'?(h.accepted?'Als akzeptabel bewertet':'Als nicht akzeptabel bewertet'):h.type==='undo'?'Anpassung rückgängig':'Lernschwellen zurückgesetzt'}</strong><span class="mono">${time(h.at)}</span></div><p>${h.value!==undefined?num(h.value)+' mm · ':''}${h.changed?`${num(h.previousLower)}–${num(h.previousUpper)} → ${num(h.nextLower)}–${num(h.nextUpper)} mm`:esc(h.reason||'Grenzen unverändert.')}</p>${h.note?`<p>${esc(h.note)}</p>`:''}</div>`).join(''):'<p class="muted small">Noch keine Bewertungen. Erzeuge im Demo-Modus eine Abweichung und bewerte den Messwert.</p>'}</div></section></div><div class="setting-footer"><a href="#setup" class="text-button muted">${icon('plug')} Einrichtung erneut öffnen</a><button type="submit" class="btn primary" ${rt.record?'disabled':''}>${icon('save')} Änderungen speichern</button></div></form>`}

function setupView(){const n=rt.setupStep;let content='';if(n===1)content=`<h2>Wie möchtest du starten?</h2><p>Probiere alle Funktionen ohne Hardware aus oder verbinde deine Messbrücke.</p><div class="connection-choices"><button class="choice-card ${rt.setupMode==='demo'?'selected':''}" data-action="setup-source" data-value="demo">${icon('wave')}<div><h3>Mit Demo-Sensor starten</h3><p>Simulierte Messwerte. Keine Hardware nötig.</p></div></button><button class="choice-card ${rt.setupMode==='bridge'?'selected':''}" data-action="setup-source" data-value="bridge">${icon('plug')}<div><h3>Eigenen Sensor verbinden</h3><p>optoNCDT 1420 über eine lokale Messbrücke.</p></div></button></div>${rt.setupMode==='bridge'?`<div class="field" style="margin-top:18px"><label for="setup-bridge-url">WebSocket-Adresse</label><input id="setup-bridge-url" type="url" value="${esc(rt.bridgeUrl)}"></div><button class="btn compact" style="margin-top:12px" data-action="connect-bridge">Verbindung herstellen ${icon('arrow')}</button>`:''}`;
 if(n===2)content=`<h2>Dein Sensor wurde erkannt.</h2><p>Prüfe, ob Modell und Verbindung zu deinem Aufbau passen.</p><div class="detected-device">${icon('box')}<div><h3>${esc(SENSOR.model)}</h3><p>Messbereich 25–50 mm · Profil ${rate(profile().rate)}</p><p>${rt.setupMode==='demo'?'Demo-Sensor · simulierte Verbindung':esc(SENSOR.interface)+' · Messbrücke'}</p></div><span class="spacer"></span>${icon('check','good')}</div><div class="info-line">${icon('info')}<span>${rt.setupMode==='demo'?'Die Demo verwendet ein Sensorprofil mit festgelegten Geräteeigenschaften.':'Die Messbrücke liefert Werte für den konfigurierten Sensor. Modell und Variante müssen zum tatsächlichen Aufbau passen.'}</span></div>`;
 if(n===3)content=`<h2>Verbindung und Signal prüfen</h2><p>Der Sensor sollte gültige Messwerte liefern. Das Objekt muss im physischen Messbereich liegen.</p><div class="check-item">${icon(rt.connected?'check':'close',rt.connected?'':'bad')} ${rt.connected?'Datenquelle ist verbunden':'Noch keine Verbindung'}</div><div class="check-item">${icon(rt.connected&&rt.value>=25&&rt.value<=50?'check':'close',rt.connected?'':'bad')} ${rt.connected?'Messwert im Bereich 25–50 mm':'Gültiger Messwert fehlt'}</div><div class="check-item">${icon('check')} Sollwert und Einheit sind eingerichtet</div><div class="wizard-reading"><div class="reading-main"><span class="reading-value">${rt.connected?num(rt.value):'—'}</span><span class="reading-unit">mm</span></div><span class="small muted">${rt.mode==='demo'?'Simulierter Messwert':'Aktueller Sensorwert'}</span></div>${!rt.connected?'<button class="btn" data-action="reconnect">Erneut verbinden</button>':''}`;
 if(n===4)content=`<h2>Deine erste Messung ist da.</h2><p>Du kannst jetzt im Monitor aufnehmen, Notizen setzen und Abweichungen bewerten.</p><div class="wizard-reading"><div class="reading-main"><span class="reading-value">${num(rt.value)}</span><span class="reading-unit">mm</span></div><div class="row good" style="justify-content:center">${icon('check')} Messung erfolgreich</div></div><div class="detected-device" style="margin-top:18px">${icon('sliders')}<div><h3>${esc(profile().name)}</h3><p>Sollwert ${num(profile().target)} mm · ${rate(profile().rate)}</p></div><span class="spacer"></span><button class="text-button" data-action="edit-profile">Bearbeiten ${icon('edit')}</button></div>`;
 return `<div class="wizard"><a href="#monitor" class="text-button muted small">${icon('back')} Zum Monitor</a><div class="wizard-intro"><span class="eyebrow">Geführte Einrichtung</span><h1 style="margin-top:10px">In vier Schritten startklar.</h1><p>Nur die Einstellungen, die du jetzt brauchst.</p></div><div class="stepper" aria-label="Einrichtungsfortschritt">${['Sensor anschließen','Gerät erkennen','Verbindung prüfen','Erste Messung'].map((s,i)=>`<div class="step ${i+1<n?'done':i+1===n?'active':''}" ${i+1===n?'aria-current="step"':''}><span class="step-circle">${i+1<n?icon('check'):i+1}</span><span>${s}</span></div>`).join('')}</div><section class="panel wizard-card">${content}<div class="wizard-actions"><button class="btn quiet" data-action="setup-back" ${n===1?'disabled':''}>${icon('back')} Zurück</button><button class="btn primary" data-action="setup-next" ${n===3&&!rt.connected?'disabled':''}>${n===4?'Zum Monitor':n===3?'Erste Messung anzeigen':'Weiter'} ${icon('arrow')}</button></div></section><p class="demo-notice">${icon('info')} ${rt.setupMode==='demo'?'Demo-Modus: Einrichtung und Messwerte werden simuliert.':'Die Einrichtung ändert keine Hardwareparameter im Sensor.'}</p></div>`}

function dialogShell(title,content,wide=false){return `<div class="dialog-head"><h2 id="dialog-title">${esc(title)}</h2><button class="icon-button" data-action="close-dialog" aria-label="Dialog schließen">${icon('close')}</button></div><div class="dialog-content">${content}</div>`}
function openDialog(type,context=null){if(rt.dialogViewer){rt.dialogViewer.dispose();rt.dialogViewer=null}dialogType=type;dialogContext=context;const d=$('#dialog');d.className=type==='sensor'?'wide':'';let title='',body='';const p=profile();
 if(type==='profile'){title='Messprofil bearbeiten';body=`<p>Sollwerte bleiben von den gelernten Auswertungsgrenzen getrennt. Neue Sollgrenzen starten einen neuen Lernstand.</p><form data-form="profile"><div class="fields"><div class="field full"><label for="profile-name">Profilname</label><input id="profile-name" name="name" value="${esc(p.name)}" required maxlength="80"></div><div class="field full"><label for="profile-description">Kurzbeschreibung</label><input id="profile-description" name="description" value="${esc(p.description)}" maxlength="180"></div><div class="field full"><label for="profile-target">Sollwert in mm</label><input id="profile-target" name="target" type="number" min="25" max="50" step=".001" value="${p.target}" required></div><div class="field"><label for="profile-lower">Untere Sollgrenze (mm)</label><input id="profile-lower" name="lower" type="number" min="25" max="50" step=".001" value="${p.lower}" required></div><div class="field"><label for="profile-upper">Obere Sollgrenze (mm)</label><input id="profile-upper" name="upper" type="number" min="25" max="50" step=".001" value="${p.upper}" required></div><div class="field"><label for="profile-rate">Profil-Messrate</label><select id="profile-rate" name="rate">${SENSOR.rates.map(n=>`<option value="${n}" ${p.rate===n?'selected':''}>${rate(n)}</option>`).join('')}</select></div><div class="field"><label for="profile-save-mode">Speichern als</label><select id="profile-save-mode" name="saveMode"><option value="update">Aktuelles Profil aktualisieren</option><option value="copy">Neues Profil anlegen</option></select></div></div><div class="dialog-error" id="dialog-error" role="alert"></div><div class="dialog-actions"><button type="button" class="btn quiet" data-action="close-dialog">Abbrechen</button><button class="btn primary" type="submit">${icon('save')} Profil speichern</button></div></form>`}
 if(type==='profile-preview'){const n=state.profiles.find(x=>x.id===context);if(!n)return;title='Profilwechsel prüfen';const changes=[['Profil',p.name,n.name],['Sollwert',num(p.target)+' mm',num(n.target)+' mm'],['Sollgrenzen',num(p.lower)+'–'+num(p.upper),num(n.lower)+'–'+num(n.upper)],['Profil-Messrate',rate(p.rate),rate(n.rate)],['Diagramm',p.window+' s',n.window+' s']];body=`<p>${esc(n.description)} Diese Einstellungen werden beim Laden übernommen:</p><div class="change-list">${changes.map(c=>`<div class="change-row"><span>${c[0]}</span><span>${esc(c[1])} → ${esc(c[2])}</span></div>`).join('')}</div><div class="dialog-actions"><button class="btn quiet" data-action="close-dialog">Abbrechen</button><button class="btn primary" data-action="apply-profile" data-id="${esc(n.id)}">Profil laden ${icon('arrow')}</button></div>`}
 if(type==='record'){title='Aufnahme vorbereiten';body=`<p>Die Messung wird mit Originalwerten, Notizen und den aktuellen Einstellungen lokal gespeichert.</p><form data-form="start-record"><div class="field"><label for="record-name">Dateiname / Messungsname</label><input id="record-name" name="name" value="${esc(p.name)} · ${new Date().toLocaleDateString('de-DE')} ${new Date().toLocaleTimeString('de-DE',{hour:'2-digit',minute:'2-digit'})}" required maxlength="100"></div><div class="metric-row"><span class="muted">Speicherort</span><span>Dieser Browser · Aufzeichnungen</span></div><div class="metric-row"><span class="muted">Quelle</span><span>${rt.mode==='demo'?'Demo · 5 Werte/s':'Sensor · Messbrücke'}</span></div><p class="info-line">${icon('info')}<span>Über CSV oder PDF kannst du die Aufnahme anschließend als Datei herunterladen.</span></p><div class="dialog-actions"><button type="button" class="btn quiet" data-action="close-dialog">Abbrechen</button><button class="btn primary" type="submit"><span class="record-dot"></span> Aufnahme starten</button></div></form>`}
 if(type==='marker'){const m=rt.markers.find(x=>x.id===context);if(!m)return;title='Ereignis bearbeiten';body=`<form data-form="edit-marker"><div class="field"><label for="edit-marker-note">Notiz bei ${formatDuration(m.t)}</label><textarea id="edit-marker-note" name="note" required maxlength="300">${esc(m.note)}</textarea></div><div class="dialog-actions"><button type="button" class="btn quiet" data-action="close-dialog">Abbrechen</button><button class="btn primary" type="submit">Notiz speichern</button></div></form>`}
 if(type==='run'){const r=state.recordings.find(x=>x.id===context);if(!r)return;title='Aufzeichnung bearbeiten';body=`<form data-form="rename-run"><div class="field"><label for="rename-run-name">Name der Messung</label><input name="name" id="rename-run-name" value="${esc(r.name)}" required maxlength="100"></div><div class="metric-row"><span class="muted">Gespeichert am</span><span>${date(r.createdAt)} · ${time(r.createdAt)}</span></div><div class="dialog-actions"><button type="button" class="btn quiet" data-action="close-dialog">Abbrechen</button><button class="btn primary" type="submit">Umbenennen</button></div></form>`}
 if(type==='connection'){title='Datenquelle wählen';body=`<p>Die Demo funktioniert sofort. Für echte Messungen verbindet eine lokale Messbrücke deinen Sensor mit dem Browser.</p><div class="connection-choices"><button class="choice-card ${rt.mode==='demo'?'selected':''}" data-action="demo">${icon('wave')}<div><h3>Demo-Modus</h3><p>Alle Abläufe mit simulierten Daten ausprobieren.</p></div></button><a class="choice-card" href="#advanced" data-action="close-dialog">${icon('plug')}<div><h3>Sensor verbinden</h3><p>Messbrücke auf der Advanced-Seite einrichten.</p></div></a></div><div class="dialog-actions"><button class="btn quiet" data-action="close-dialog">Schließen</button></div>`}
 if(type==='help'){title='Gut zu wissen';body=`<p>Der Sensor Monitor begleitet dich vom ersten Messwert bis zum Bericht.</p><div class="stack"><div><h3>1. Messen & aufnehmen</h3><p class="small muted">Wähle ein Profil. Eine Liveanzeige wird erst durch „Aufnahme starten“ gespeichert. „Stoppen & speichern“ legt sie unter Aufzeichnungen ab.</p></div><div><h3>2. Aus Abweichungen lernen</h3><p class="small muted">Im Demo-Modus kannst du eine Abweichung erzeugen und bewerten. Akzeptierte Werte erweitern die Auswertungsgrenzen. Deine Sollgrenzen bleiben unverändert.</p></div><div><h3>3. Daten behalten</h3><p class="small muted">Profile und Aufnahmen bleiben lokal in diesem Browser. Lade wichtige Messungen als CSV oder PDF herunter, bevor du Browserdaten löschst.</p></div><div><h3>4. Echte Hardware</h3><p class="small muted">Diese Anwendung verwendet ohne Messbrücke Demodaten. Das 3D-Modell ist eine schematische Orientierungshilfe. Die LED-Erklärungen folgen dem Sensorhandbuch.</p></div></div><div class="dialog-actions"><a class="btn" href="https://www.micro-epsilon.com/fileadmin/download/manuals/man--optoNCDT-1420--en.pdf" target="_blank" rel="noopener">Sensorhandbuch ${icon('arrow')}</a><button class="btn primary" data-action="close-dialog">Verstanden</button></div>`}
 if(type==='bridge-help'){title='Messbrücke anschließen';body=`<p>Der Browser spricht den RS422-Sensor nicht direkt an. Eine lokale Anwendung liest den Sensor und sendet JSON-Nachrichten über WebSocket.</p><pre style="font:11px/1.7 var(--mono);padding:15px;background:var(--bg);border-radius:6px;overflow:auto">${esc(JSON.stringify({value:37.501,unit:'mm',sensor:'optoNCDT 1420-25',state:'green',output:'green'},null,2))}</pre><p class="info-line">${icon('info')}<span>value muss eine gültige Zahl in mm sein. Modell muss zum konfigurierten 1420-25 passen. LED-Werte: green, yellow, red, off oder unknown. Fehlende LED-Daten werden als unbekannt angezeigt. Nutze eine vertrauenswürdige lokale Brücke; bei HTTPS kann WSS erforderlich sein.</span></p><div class="dialog-actions"><button class="btn primary" data-action="close-dialog">Verstanden</button></div>`}
 if(type==='sensor'){title='Sensorstatus verstehen';body=`<p>${rt.mode==='demo'?'Die gezeigten Zustände sind simuliert. Wähle eine LED-Farbe, um ihre Bedeutung kennenzulernen.':'Die LED-Anzeige verwendet die von deiner Messbrücke gemeldeten Zustände.'}</p><div class="sensor-dialog-grid"><div><div class="sensor-large" id="large-viewer"><div class="viewer-help">Ziehen zum Drehen · Scrollen zum Zoomen</div></div><div class="viewer-controls"><span class="small muted">Schematische 3D-Ansicht · kein CAD-Modell</span><button class="text-button small" data-action="reset-viewer">${icon('reset')} Ansicht zurücksetzen</button></div></div><div>${['state','output'].map(name=>`<section class="sensor-detail"><div class="sensor-detail-header"><span class="dot" id="dialog-${name}-dot" style="color:${ledColor(rt.led[name])}"></span><h3>${name==='state'?'State':'Output'}-LED</h3></div>${rt.mode==='demo'?`<div class="led-options" aria-label="${name} LED simulieren">${['green','yellow','red','off'].map(c=>`<button class="led-option ${rt.led[name]===c?'active':''}" data-action="led" data-led="${name}" data-value="${c}" aria-label="${name}-LED ${({green:'grün',yellow:'gelb',red:'rot',off:'aus'})[c]}" style="--led:${ledColor(c)}"><span></span></button>`).join('')}</div>`:''}<p class="led-explanation" id="led-${name}-description">${ledMeaning(name,rt.led[name])}</p></section>`).join('')}<div class="info-line">${icon('info')}<span>Hardwarestatus und gelernte Sollwertbewertung sind getrennt.</span></div></div></div>`}
 d.innerHTML=dialogShell(title,body);if(!d.open)d.showModal();if(type==='sensor'){rt.dialogViewer=createSensorViewer($('#large-viewer'),{initialState:rt.led,onSelect:name=>{$(`#led-${name}-description`)?.scrollIntoView({block:'nearest'});toast(`${name==='state'?'State':'Output'}: ${ledMeaning(name,rt.led[name])}`)}})}
}
function closeDialog(){rt.dialogViewer?.dispose();rt.dialogViewer=null;$('#dialog').close();dialogType='';dialogContext=null}

function render(){const focused=document.activeElement;const focusedInApp=focused&&$('#app').contains(focused);let focusSelector='';if(focusedInApp){if(focused.id)focusSelector='#'+CSS.escape(focused.id);else if(focused.dataset.action){focusSelector='[data-action="'+CSS.escape(focused.dataset.action)+'"]';for(const k of ['id','value','view'])if(focused.dataset[k])focusSelector+='[data-'+k+'="'+CSS.escape(focused.dataset[k])+'"]'}else if(focused.dataset.field){focusSelector='[data-field="'+CSS.escape(focused.dataset.field)+'"]';if(focused.value)focusSelector+='[value="'+CSS.escape(focused.value)+'"]'}}rt.viewer?.dispose();rt.viewer=null;rt.charts=[];const main=rt.route==='recordings'?recordingsView():rt.route==='advanced'?advancedView():rt.route==='setup'?setupView():monitor();$('#app').innerHTML=header()+`<main id="main" class="main" tabindex="-1">${globalNotices()}${main}${footer()}</main>`;document.title=`${{monitor:'Monitor',recordings:'Aufzeichnungen',advanced:'Advanced',setup:'Einrichtung'}[rt.route]} · Micro-Epsilon`;if(rt.route==='monitor'){rt.viewer=createSensorViewer($('#mini-viewer'),{initialState:rt.led,onSelect:name=>openDialog('sensor',name)});updateLive();const canvas=$('#live-chart');canvas.addEventListener('pointermove',chartHover);canvas.addEventListener('pointerleave',()=>$('#live-tooltip')?.classList.add('hidden'))}drawCharts();if(focusSelector)$(focusSelector)?.focus({preventScroll:true});if(rt.search&&rt.route==='recordings')document.querySelectorAll('[data-run-id]').forEach(row=>row.hidden=!row.textContent.toLocaleLowerCase().includes(rt.search.toLocaleLowerCase()))}

function drawChart(canvas,{points,reference=null,profile:p,start=0,end=60,markers=[],offset=0,refOffset=0,cursor=null,light=false}){if(!canvas)return;const rect=canvas.getBoundingClientRect();if(rect.width<1||rect.height<1)return;const ratio=Math.min(devicePixelRatio||1,2),w=rect.width,h=rect.height;canvas.width=Math.round(w*ratio);canvas.height=Math.round(h*ratio);const ctx=canvas.getContext('2d');ctx.scale(ratio,ratio);const colors=getComputedStyle(document.documentElement);const text=light?'#70818e':colors.getPropertyValue('--muted').trim(),line=light?'#e0e7ec':colors.getPropertyValue('--line').trim(),accent=light?'#007b86':colors.getPropertyValue('--accent').trim();const left=w<400?53:62,right=12,top=15,bottom=29,pw=w-left-right,ph=h-top-bottom;const data=points.filter(x=>x.t>=start&&x.t<=end&&Number.isFinite(x.value));const ref=reference?.filter(x=>x.t+refOffset>=start&&x.t+refOffset<=end&&Number.isFinite(x.value))||[];const vals=[p.lower,p.upper,p.target,...data.map(x=>x.value),...ref.map(x=>x.value)];let low=Math.min(...vals),high=Math.max(...vals);const pad=Math.max((high-low)*.3,.012);low-=pad;high+=pad;const x=t=>left+(t-start)/Math.max(.001,end-start)*pw,y=v=>top+ph-(v-low)/(high-low)*ph;
 ctx.clearRect(0,0,w,h);ctx.font='9px "JetBrains Mono"';ctx.textBaseline='middle';ctx.fillStyle=text;ctx.strokeStyle=line;ctx.lineWidth=.7;const steps=4;for(let i=0;i<=steps;i++){const yy=top+ph*i/steps;ctx.beginPath();ctx.moveTo(left,yy);ctx.lineTo(w-right,yy);ctx.stroke();ctx.textAlign='right';ctx.fillText(num(high-(high-low)*i/steps-offset),left-9,yy)}
 ctx.save();ctx.beginPath();ctx.rect(left,top,pw,ph);ctx.clip();ctx.fillStyle=light?'#008a8807':'#4edea308';ctx.fillRect(left,y(p.upper),pw,y(p.lower)-y(p.upper));for(const value of[p.lower,p.upper]){ctx.strokeStyle=light?'#92a4ae':'#6c7f8c';ctx.setLineDash([4,5]);ctx.lineWidth=.7;ctx.beginPath();ctx.moveTo(left,y(value));ctx.lineTo(w-right,y(value));ctx.stroke()}ctx.setLineDash([]);const draw=(arr,shift,color,dash=[])=>{if(arr.length<1)return;ctx.strokeStyle=color;ctx.lineWidth=1.65;ctx.setLineDash(dash);ctx.beginPath();arr.forEach((pt,i)=>{i?ctx.lineTo(x(pt.t+shift),y(pt.value)):ctx.moveTo(x(pt.t+shift),y(pt.value))});ctx.stroke();ctx.setLineDash([])};draw(data,0,accent);draw(ref,refOffset,light?'#748590':'#a8b2bf',[4,4]);
 markers.filter(m=>m.t>=start&&m.t<=end).forEach(m=>{ctx.strokeStyle=light?'#9caab3':'#657987';ctx.setLineDash([2,4]);ctx.beginPath();ctx.moveTo(x(m.t),top+8);ctx.lineTo(x(m.t),top+ph);ctx.stroke();ctx.setLineDash([]);ctx.fillStyle=accent;ctx.beginPath();ctx.arc(x(m.t),top+6,2.5,0,Math.PI*2);ctx.fill()});if(cursor!==null){ctx.strokeStyle=light?'#1b3548':'#dfe2eb';ctx.lineWidth=1;ctx.beginPath();ctx.moveTo(x(cursor),top);ctx.lineTo(x(cursor),top+ph);ctx.stroke()}ctx.restore();ctx.fillStyle=text;ctx.font='9px "JetBrains Mono"';ctx.textBaseline='top';for(let i=0;i<=4;i++){const t=start+(end-start)*i/4;ctx.textAlign=i===0?'left':i===4?'right':'center';ctx.fillText(formatDuration(t),x(t),h-bottom+10)}canvas._plot={start,end,left,pw,data,x,y,w,h,offset};
}
function drawCharts(){const p=profile();if($('#live-chart'))drawChart($('#live-chart'),{points:rt.points,profile:p,start:Math.max(0,rt.elapsed-rt.window),end:rt.elapsed,markers:rt.markers,offset:rt.zeroOffset});if(rt.route==='recordings'&&rt.analysis){const runs=[...rt.selected].map(id=>state.recordings.find(r=>r.id===id)).filter(Boolean),r=runs[0];if(!r)return;if(rt.analysis==='report'){drawChart($('#report-chart'),{points:r.points,profile:r.profile,start:rt.reportStart,end:rt.reportEnd,markers:r.markers,light:true});return}if(rt.analysis==='compare'&&runs.length===2){drawChart($('#analysis-chart'),{points:r.points,reference:runs[1].points,profile:r.profile,start:0,end:Math.max(r.duration,runs[1].duration+rt.offset),markers:r.markers,refOffset:rt.offset});updateComparison(r,runs[1])}else if(rt.analysis==='replay'){const window=rt.replayWindow||r.duration;let start=Math.max(0,rt.replayTime-window*.8);start=Math.min(start,Math.max(0,r.duration-window));drawChart($('#analysis-chart'),{points:r.points,profile:r.profile,start,end:Math.min(r.duration,start+window),markers:r.markers,cursor:rt.replayTime});const current=r.points.reduce((a,b)=>Math.abs(b.t-rt.replayTime)<Math.abs(a.t-rt.replayTime)?b:a,r.points[0]);if($('#replay-value'))$('#replay-value').textContent=`${num(current?.value)} mm · ${r.source==='demo'?'Demodaten':'Sensordaten'}`}}}
function updateComparison(a,b){const diffs=[];for(const pt of a.points){const t=pt.t-rt.offset;if(t<0||t>b.duration)continue;let lo=0,hi=b.points.length-1;while(lo<hi){const mid=Math.floor((lo+hi)/2);if(b.points[mid].t<t)lo=mid+1;else hi=mid}const point=b.points[lo];const previous=b.points[Math.max(0,lo-1)];const nearest=Math.abs(point.t-t)<Math.abs(previous.t-t)?point:previous;if(Math.abs(nearest.t-t)<=.21)diffs.push(pt.value-nearest.value)}const mean=diffs.length?diffs.reduce((a,b)=>a+b,0)/diffs.length:null;$('#compare-mean').textContent=mean===null?'—':num(mean)+' mm';$('#compare-max').textContent=diffs.length?num(Math.max(...diffs.map(Math.abs)))+' mm':'—';$('#compare-count').textContent=String(diffs.length)}
function chartHover(e){const canvas=e.currentTarget,plot=canvas._plot,tooltip=$('#live-tooltip');if(!plot||!plot.data.length||!tooltip)return;const rect=canvas.getBoundingClientRect(),tx=plot.start+((e.clientX-rect.left-plot.left)/plot.pw)*(plot.end-plot.start);const point=plot.data.reduce((a,b)=>Math.abs(b.t-tx)<Math.abs(a.t-tx)?b:a);tooltip.textContent=`${formatDuration(point.t)} · ${vnum(point.value)} mm`;tooltip.classList.remove('hidden');tooltip.style.left=Math.min(plot.w-tooltip.offsetWidth-4,Math.max(4,e.clientX-rect.left+10))+'px';tooltip.style.top=Math.max(4,e.clientY-rect.top-32)+'px'}
function updateLive(){const p=profile();const reading=$('#reading-value');if(reading)reading.textContent=rt.connected?vnum(rt.value):'—';if($('#deviation-value'))$('#deviation-value').textContent=num(rt.value-p.target)+' mm';const pointer=$('#tolerance-pointer');if(pointer)pointer.style.left=Math.max(1,Math.min(99,15+(rt.value-p.lower)/(p.upper-p.lower)*70))+'%';const status=$('#reading-state');if(status){const inside=rt.value>=p.lower&&rt.value<=p.upper;status.className='reading-state '+(!rt.connected?'muted':inside?'good':'warn');status.innerHTML=`<span class="dot"></span>${!rt.connected?'Warte auf gültige Messwerte':inside?'Innerhalb des Sollbereichs':rt.value>=p.learnedLower&&rt.value<=p.learnedUpper?'Außerhalb Sollbereich · als akzeptabel gelernt':'Außerhalb des Sollbereichs'}`}
 if($('#record-duration')&&rt.record)$('#record-duration').textContent=formatDuration(rt.elapsed-rt.record.startElapsed);if($('#sample-count'))$('#sample-count').textContent=`${rt.points.length} Darstellungswerte`;for(const name of['state','output']){const dot=$(`#${name}-dot`);if(dot)dot.style.color=ledColor(rt.led[name])}rt.viewer?.setStatus(rt.led);rt.dialogViewer?.setStatus(rt.led)}
function addValue(value,{led=null}={}){if(!Number.isFinite(value))return;if(rt.mode==='demo')rt.elapsed+=1/DISPLAY_RATE;else rt.elapsed=Math.max(0,(performance.now()-rt.bridgeStart)/1000);rt.value=value;const point={t:rt.elapsed,value,version:profile().version};rt.points.push(point);rt.points=rt.points.filter(p=>p.t>=rt.elapsed-65);if(led){rt.led=led}else if(rt.scenario==='normal'){rt.led={state:Math.abs(value-37.5)<.001?'yellow':'green',output:state.settings.output==='analog'?'red':'green'}}if(rt.record)rt.record.points.push({...point,t:Math.max(0,rt.elapsed-rt.record.startElapsed)});const p=profile();if(rt.elapsed>rt.cooldown&&!rt.deviation&&(value<p.learnedLower||value>p.learnedUpper)){rt.deviation={value,t:rt.elapsed,profile:clone(p)};rt.lastFeedback=null;if(rt.route==='monitor'){const target=$('#learning-notice');if(target)target.innerHTML=learningNotice()}}if(rt.mode==='demo'||performance.now()-(rt.lastDraw||0)>100){updateLive();drawCharts();rt.lastDraw=performance.now()}}
function startRecord(name){if(rt.unsaved){toast('Sichere zuerst die noch nicht gespeicherte Aufnahme.');return}if(!rt.connected){toast('Verbinde zuerst eine Datenquelle.');return}rt.paused=false;rt.lastSaved=null;rt.deviation=null;rt.lastFeedback=null;rt.record={id:generateId('run'),name,createdAt:new Date().toISOString(),source:rt.mode==='demo'?'demo':'sensor',sensor:SENSOR.model,profile:clone(profile()),profileAtStart:clone(profile()),points:[{t:0,value:rt.value,version:profile().version}],markers:[],feedback:[],parameterHistory:[],storage:'Browser · lokal',displayRate:DISPLAY_RATE,zeroOffset:rt.zeroOffset,startElapsed:rt.elapsed};closeDialog();render();toast('Aufnahme läuft. Messwerte werden erfasst.')}
function finishRecord(interrupted=false){const r=rt.record;if(!r)return null;r.duration=Math.max(.2,rt.elapsed-r.startElapsed);r.profile=clone(profile());r.interrupted=interrupted;if(r.source!=='demo')r.displayRate=Math.round(r.points.length/r.duration*100)/100;delete r.startElapsed;rt.record=null;return r}
function saveRecording(r){if(!r)return;const old=state.recordings;state.recordings=[r,...old.filter(x=>x.id!==r.id)];if(persist()){rt.unsaved=null;rt.lastSaved=r;toast('Aufzeichnung lokal gespeichert.');render()}else{state.recordings=old;rt.unsaved=r;render()}}
function stopRecord(){if(!rt.record)return;const r=finishRecord();rt.saving=true;render();setTimeout(()=>{rt.saving=false;saveRecording(r)},300)}
function interruptRecord(){if(rt.record){rt.unsaved=finishRecord(true);toast('Aufnahme unterbrochen. Sichere die bisher erfassten Daten.')}}
function useDemo(){if(rt.record||rt.saving){toast('Bitte zuerst die laufende Aufnahme stoppen.');return}disconnectSocket();rt.mode='demo';rt.connected=true;rt.paused=false;rt.connectionError='';rt.scenario='normal';rt.led={state:'green',output:'green'};rt.value=profile().target;rt.elapsed=60;rt.points=makeDemoPoints(60,0,0,profile().target);rt.markers=[];rt.deviation=null;rt.lastFeedback=null;rt.zeroOffset=0;closeDialog();render();toast('Demo-Sensor verbunden.')}
function disconnectSocket(){clearTimeout(rt.socketTimer);if(rt.socket){rt.socket.onclose=null;rt.socket.onerror=null;rt.socket.close();rt.socket=null}}
function connectBridge(){if(rt.record){toast('Bitte zuerst die Aufnahme stoppen.');return}const field=$('#setup-bridge-url')||$('#bridge-url');const url=field?.value.trim()||rt.bridgeUrl;if(!/^wss?:\/\//i.test(url)){toast('Gib eine gültige ws://- oder wss://-Adresse ein.');return}disconnectSocket();rt.mode='bridge';rt.connected=false;rt.bridgeUrl=url;rt.connectionError='';rt.paused=false;rt.points=[];rt.markers=[];rt.deviation=null;rt.lastFeedback=null;rt.zeroOffset=0;rt.elapsed=0;rt.bridgeStart=performance.now();rt.led={state:'unknown',output:'unknown'};closeDialog();render();toast('Verbindung zur Messbrücke wird hergestellt …');let gotValue=false;try{const socket=new WebSocket(url);rt.socket=socket;rt.socketTimer=setTimeout(()=>{if(!gotValue){disconnectSocket();connectionFailed('Die Messbrücke liefert keine gültigen Werte. Adresse, lokalen Dienst und Sensor prüfen.')}},8000);socket.onmessage=event=>{let data;try{data=JSON.parse(event.data)}catch{return}if(!Number.isFinite(data.value)||data.unit!=='mm')return;if(data.sensor&&data.sensor!==SENSOR.model){disconnectSocket();connectionFailed('Das gemeldete Sensormodell passt nicht zum eingerichteten optoNCDT 1420-25.');return}if(data.value<SENSOR.rangeStart||data.value>SENSOR.rangeEnd){connectionFailed('Messwert außerhalb des physischen Messbereichs (25–50 mm). Sensorposition und Sensorkonfiguration prüfen.');return}const wasConnected=rt.connected;if(!gotValue)rt.bridgeStart=performance.now();gotValue=true;clearTimeout(rt.socketTimer);rt.lastBridgeAt=performance.now();rt.connected=true;rt.connectionError='';if(rt.paused)return;const allowed=['green','yellow','red','off','unknown'];const led={state:allowed.includes(data.state)?data.state:'unknown',output:allowed.includes(data.output)?data.output:'unknown'};addValue(data.value,{led});if(!wasConnected)render()};socket.onerror=()=>connectionFailed('Die lokale Messbrücke ist nicht erreichbar. Dienst und WebSocket-Adresse prüfen.');socket.onclose=()=>connectionFailed('Die Verbindung zur Messbrücke wurde getrennt. Lokalen Dienst und Sensorverbindung prüfen.')}catch(e){connectionFailed('Die Verbindung konnte nicht geöffnet werden. WebSocket-Adresse und Browserfreigaben prüfen.')}}
function connectionFailed(message){if(rt.connected)interruptRecord();rt.connected=false;rt.connectionError=message;rt.led={state:'unknown',output:'unknown'};render()}
function reconnect(){if(rt.mode==='demo'){rt.connected=true;rt.connectionError='';rt.scenario='normal';rt.led={state:'green',output:'green'};render();toast('Demo-Verbindung wiederhergestellt.')}else connectBridge()}

async function handleAction(el,event){const action=el.dataset.action;switch(action){
 case'close-dialog':closeDialog();break;
 case'theme':{const theme=document.documentElement.dataset.theme==='light'?'dark':'light';document.documentElement.dataset.theme=theme;try{localStorage.setItem('me-theme',theme)}catch{}render();break}
 case'help':openDialog('help');break;case'bridge-help':openDialog('bridge-help');break;case'connection':openDialog('connection');break;case'connect-bridge':connectBridge();break;case'demo':useDemo();break;case'reconnect':reconnect();break;
 case'dismiss-setup':state.setupComplete=true;persist();render();break;
 case'edit-profile':if(rt.record){toast('Das Profil kann nach dem Stoppen der Aufnahme geändert werden.');break}openDialog('profile');break;
 case'apply-profile':{const p=state.profiles.find(p=>p.id===el.dataset.id);if(!p)break;state.activeProfileId=p.id;rt.window=p.window;rt.zeroOffset=0;rt.points=rt.mode==='demo'?makeDemoPoints(60,0,0,p.target):[];if(rt.mode==='demo'){rt.elapsed=60;rt.value=p.target;}rt.markers=[];rt.deviation=null;rt.lastFeedback=null;rt.cooldown=0;persist();closeDialog();render();toast(`Profil „${p.name}“ geladen.`);break}
 case'record':if(rt.record)stopRecord();else if(rt.unsaved)toast('Sichere zuerst die noch nicht gespeicherte Aufnahme.');else openDialog('record');break;
 case'retry-save':saveRecording(rt.unsaved);break;case'export-unsaved':exportRecordingCSV(rt.unsaved);break;
 case'pause':if(rt.record)break;rt.paused=!rt.paused;render();break;
 case'zero':if(rt.record){toast('Der Nullpunkt bleibt während einer Aufnahme unverändert.');break}rt.zeroOffset=rt.zeroOffset?0:rt.value;render();toast(rt.zeroOffset?'Anzeige auf Null gesetzt. Originaldaten bleiben erhalten.':'Absoluter Sensorabstand wird angezeigt.');break;
 case'window':rt.window=Number(el.dataset.value);render();break;
 case'edit-marker':openDialog('marker',el.dataset.id);break;
 case'sensor':openDialog('sensor',el.dataset.led);break;
 case'reset-viewer':rt.dialogViewer?.reset();break;
 case'led':{if(rt.mode!=='demo')break;rt.scenario='led';rt.led[el.dataset.led]=el.dataset.value;rt.viewer?.setStatus(rt.led);rt.dialogViewer?.setStatus(rt.led);for(const name of['state','output']){$(`#dialog-${name}-dot`).style.color=ledColor(rt.led[name]);$(`#led-${name}-description`).textContent=ledMeaning(name,rt.led[name])}$('#dialog').querySelectorAll('.led-option').forEach(b=>b.classList.toggle('active',rt.led[b.dataset.led]===b.dataset.value));updateLive();break}
 case'toggle-learning':{const p=clone(profile());p.learning=!p.learning;setProfile(p);persist();render();toast(p.learning?'Lernen ist wieder aktiv.':'Lernen ist pausiert. Bewertungen bleiben möglich.');break}
 case'undo-learning':setProfile(undoLearning(profile()));if(rt.record)rt.record.parameterHistory.push({...clone(profile().history.at(-1)),t:rt.elapsed-rt.record.startElapsed});rt.lastFeedback=null;persist();render();toast('Letzte Lernanpassung rückgängig gemacht.');break;
 case'reset-learning':setProfile(resetLearning(profile()));if(rt.record)rt.record.parameterHistory.push({...clone(profile().history.at(-1)),t:rt.elapsed-rt.record.startElapsed});rt.lastFeedback=null;persist();render();toast('Gelernte Grenzen auf die Sollgrenzen zurückgesetzt.');break;
 case'simulate-deviation':if(rt.mode==='demo'&&rt.connected){rt.paused=false;rt.cooldown=0;rt.scenario='normal';const p=profile();addValue(Math.min(49.99,Math.max(p.upper,p.learnedUpper)+.025));render()}break;
 case'simulate-disconnect':if(rt.mode!=='demo')break;if(rt.connected){interruptRecord();rt.connected=false;rt.connectionError='Die Demo simuliert einen Verbindungsabbruch. Mit „Erneut verbinden“ kannst du fortfahren.';rt.led={state:'unknown',output:'unknown'};render()}else reconnect();break;
 case'feedback':{if(!rt.deviation)break;const d=rt.deviation,note=$('#feedback-note')?.value||'',accepted=el.dataset.accepted==='true';const result=acceptFeedback(profile(),d.value,accepted,note,d.t);setProfile(result.profile);rt.feedback.push(result.event);if(rt.record){const converted={...result.event,t:Math.max(0,d.t-rt.record.startElapsed)};rt.record.feedback.push(converted);if(result.event.changed)rt.record.parameterHistory.push({...converted,t:Math.max(0,rt.elapsed-rt.record.startElapsed)});rt.record.markers.push({id:generateId('feedback-note'),t:converted.t,note:`${accepted?'Akzeptabel':'Nicht akzeptabel'}: ${num(d.value)} mm${note?' · '+note:''}`})}rt.deviation=null;rt.lastFeedback=result.event;rt.cooldown=rt.elapsed+5;persist();render();break}
 case'dismiss-deviation':rt.deviation=null;rt.cooldown=rt.elapsed+10;render();break;case'dismiss-feedback':rt.lastFeedback=null;render();break;
 case'run-menu':openDialog('run',el.dataset.id);break;
 case'analysis':{rt.analysis=el.dataset.view;rt.offset=0;rt.replayPlaying=false;rt.replayTime=0;rt.reportStart=0;rt.reportEnd=recording()?.duration||60;render();$('.analysis-panel')?.scrollIntoView({behavior:'smooth',block:'start'});break}
 case'close-analysis':rt.analysis=null;rt.replayPlaying=false;render();break;
 case'csv':if(recording()){exportRecordingCSV(recording());toast('CSV-Datei heruntergeladen.')}break;
 case'pdf':if(recording()){try{exportReportPDF(recording(),{start:rt.reportStart,end:rt.reportEnd});toast('PDF-Bericht heruntergeladen.')}catch(e){toast(e.message)}}break;
 case'align':rt.offset=0;render();toast('Beide Messungen beginnen bei 00:00.');break;
 case'replay-toggle':{const r=recording();if(rt.replayTime>=r.duration)rt.replayTime=0;rt.replayPlaying=!rt.replayPlaying;render();break}
 case'replay-window':rt.replayWindow=Number(el.dataset.value);render();break;
 case'jump-marker':rt.replayTime=Number(el.dataset.value);rt.replayPlaying=false;render();break;
 case'setup-source':rt.setupMode=el.dataset.value;render();break;
 case'setup-back':rt.setupStep=Math.max(1,rt.setupStep-1);render();break;
 case'setup-next':if(rt.setupStep===1){if(rt.setupMode==='demo')useDemo();else if(!rt.connected||rt.mode!=='bridge'){toast('Verbinde zuerst die Messbrücke.');break}}if(rt.setupStep===4){state.setupComplete=true;persist();rt.setupStep=1;route('monitor');toast('Einrichtung abgeschlossen. Du kannst mit der Aufnahme beginnen.')}else{rt.setupStep++;render();const heading=$('.wizard-card h2');if(heading){heading.tabIndex=-1;heading.focus({preventScroll:true})}}break;
 }}

document.addEventListener('click',event=>{if(event.target.closest('.skip-link')){event.preventDefault();$('#main')?.focus();return}const el=event.target.closest('[data-action]');if(el&&!el.disabled){handleAction(el,event).catch(e=>toast(e.message))}});
document.addEventListener('submit',event=>{const form=event.target.closest('[data-form]');if(!form)return;event.preventDefault();const data=new FormData(form);try{switch(form.dataset.form){
 case'marker':{const note=data.get('note').trim();if(!note)return;const m={id:generateId('note'),t:rt.elapsed,note};rt.markers.push(m);if(rt.record)rt.record.markers.push({...m,t:Math.max(0,m.t-rt.record.startElapsed)});render();toast('Notiz mit Zeitpunkt hinzugefügt.');break}
 case'edit-marker':{const note=data.get('note').trim();const marker=rt.markers.find(x=>x.id===dialogContext);if(marker)marker.note=note;if(rt.record){const rm=rt.record.markers.find(x=>x.id===dialogContext);if(rm)rm.note=note}closeDialog();render();toast('Notiz aktualisiert.');break}
 case'profile':{const old=profile(),target=Number(data.get('target')),lower=Number(data.get('lower')),upper=Number(data.get('upper'));if(!(lower<upper&&target>=lower&&target<=upper&&lower>=25&&upper<=50)){ $('#dialog-error').textContent='Sollwert muss zwischen den Grenzen liegen. Der Sensor misst von 25 bis 50 mm.';break}const p=clone(old),changed=target!==p.target||lower!==p.lower||upper!==p.upper;p.name=data.get('name').trim();p.description=data.get('description').trim();p.target=target;p.lower=lower;p.upper=upper;p.rate=Number(data.get('rate'));if(changed){p.learnedLower=lower;p.learnedUpper=upper;p.version++;p.history.push({id:generateId('profile-change'),type:'profile',at:new Date().toISOString(),version:p.version,changed:true,previousLower:old.learnedLower,previousUpper:old.learnedUpper,nextLower:lower,nextUpper:upper,reason:'Sollgrenzen im Profil geändert; Lernstand neu gestartet.'})}if(data.get('saveMode')==='copy'){p.id=generateId('profile');p.history=[];p.version=1;state.profiles.push(p);state.activeProfileId=p.id}else setProfile(p);if(changed){rt.points=rt.mode==='demo'?makeDemoPoints(60,0,0,target):[];if(rt.mode==='demo'){rt.value=target;rt.elapsed=60;}rt.zeroOffset=0;rt.markers=[];rt.deviation=null;rt.lastFeedback=null}const saved=persist();closeDialog();render();if(saved)toast('Messprofil gespeichert.');break}
 case'start-record':startRecord(data.get('name').trim());break;
 case'rename-run':{const r=state.recordings.find(x=>x.id===dialogContext);if(r)r.name=data.get('name').trim();const saved=persist();closeDialog();render();if(saved)toast('Messung umbenannt.');break}
 case'settings':{if(rt.record){toast('Bitte zuerst die Aufnahme stoppen.');break}const p=clone(profile());p.rate=Number(data.get('rate'));p.window=Number(data.get('window'));setProfile(p);rt.window=p.window;rt.bridgeUrl=data.get('bridgeUrl').trim();state.settings.bridgeUrl=rt.bridgeUrl;state.settings.rate=p.rate;if(persist())toast('Einstellungen für künftige Messungen gespeichert.');render();break}
 }}catch(e){toast(e.message)}});
document.addEventListener('change',event=>{const el=event.target;const field=el.dataset.field;if(!field)return;switch(field){case'profile':if(el.value!==profile().id)openDialog('profile-preview',el.value);el.value=profile().id;break;case'run':if(el.checked){if(rt.selected.size>=2){el.checked=false;toast('Wähle höchstens zwei Messungen für einen Vergleich.');break}rt.selected.add(el.value)}else rt.selected.delete(el.value);rt.analysis=null;rt.replayPlaying=false;render();break;case'speed':rt.replaySpeed=Number(el.value);break;case'report-start':case'report-end':{const r=recording(),start=field==='report-start'?Number(el.value):rt.reportStart,end=field==='report-end'?Number(el.value):rt.reportEnd;try{slicePoints(r,start,end);rt.reportStart=start;rt.reportEnd=end;render()}catch(e){el.value=field==='report-start'?rt.reportStart:rt.reportEnd;toast(e.message)}break}}});
document.addEventListener('input',event=>{const el=event.target;if(el.id==='run-search'){rt.search=el.value;const query=el.value.toLocaleLowerCase();document.querySelectorAll('[data-run-id]').forEach(row=>row.hidden=!row.textContent.toLocaleLowerCase().includes(query))}if(el.dataset.field==='offset'){rt.offset=Number(el.value);$('#offset-label').textContent=rt.offset.toFixed(1)+' s';drawCharts()}if(el.dataset.field==='replay'){rt.replayTime=Number(el.value);rt.replayPlaying=false;$('#replay-time').textContent=formatDuration(rt.replayTime);drawCharts()}});
$('#dialog').addEventListener('close',()=>{rt.dialogViewer?.dispose();rt.dialogViewer=null;dialogType='';dialogContext=null});
$('#dialog').addEventListener('click',event=>{if(event.target===$('#dialog')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeDialog()}});
function readRoute(){const name=location.hash.slice(1);rt.route=['monitor','recordings','advanced','setup'].includes(name)?name:'monitor';rt.replayPlaying=false;render()}
window.addEventListener('hashchange',()=>{closeDialog();readRoute();window.scrollTo(0,0)});
window.addEventListener('resize',()=>drawCharts());
try{document.documentElement.dataset.theme=localStorage.getItem('me-theme')||'dark'}catch{document.documentElement.dataset.theme='dark'}
rt.window=profile().window;rt.value=profile().target;rt.points=makeDemoPoints(60,0,0,profile().target);readRoute();document.fonts.ready.then(()=>drawCharts());
setInterval(()=>{const now=performance.now(),dt=Math.min(1,(now-lastTick)/1000);lastTick=now;if(rt.mode==='demo'&&rt.connected&&!rt.paused){rt.tick++;const t=rt.elapsed+1/DISPLAY_RATE,p=profile(),value=p.target+Math.sin(t*1.23)*.011+Math.sin(t*4.7)*.003+Math.sin(t*.31)*.004;addValue(Math.round(value*1e6)/1e6)}if(rt.mode==='bridge'&&rt.connected&&now-rt.lastBridgeAt>4000){disconnectSocket();connectionFailed('Seit vier Sekunden wurden keine neuen Messwerte empfangen. Sensor und Messbrücke prüfen.')}if(rt.replayPlaying&&rt.route==='recordings'){const r=recording();if(r){rt.replayTime=Math.min(r.duration,rt.replayTime+dt*rt.replaySpeed);if(rt.replayTime>=r.duration){rt.replayPlaying=false;render()}else{const range=$('[data-field="replay"]');if(range)range.value=rt.replayTime;if($('#replay-time'))$('#replay-time').textContent=formatDuration(rt.replayTime);drawCharts()}}}},200);
window.addEventListener('beforeunload',event=>{if(rt.record||rt.unsaved){event.preventDefault();event.returnValue=''}});
